import store
import warm

# `queued`: admitted, waiting for room to start (G6).
# `blocked`: a part of a split, waiting for the parts it follows to land.
# `split`: a request decomposed into parts; it tracks them and lands with them.
ACTIVE = ("queued", "ready", "running", "turn", "needs_you", "waiting", "blocked", "split")
FINISHED = ("landed", "closed", "failed", "stopped")
TURN_STAGES = ("scope", "discover", "plan", "define", "specify", "falsify", "implement", "refactor", "review",
               "prove",
               "comprehend", "ci_fix", "onboard",
               "learn", "grade")
# The turns asked to say what surprised them (briefs.SURPRISES): what the
# factory did not know, for learn.
SURPRISING = ("specify", "implement", "prove")
ORPHAN = re.compile(r"^wipp-j[0-9a-f]{12}$")


# A quality tool's exit code for "the measurement is broken, not the code".
TOOL_BROKEN = 2
TRANSIENT_TRIES = 3
# G9.3: each job's steps run as messages on iii's queue, one job's in order
# (FIFO, grouped by job) and different jobs' side by side. Persisted by the
# queue worker on the volume, redelivered after an engine restart, and seen
# by iii (depth, failures, dead letters). A stage can run for a long time
# (checks, quality), hence two hours rather than the queue's thirty minutes.

"actions"
"alert"
"bad"
"button"
"muted"
"number"
"ok"
"outcome"
"warn"
// V5's evidence: is verification enough to retire code review? Two numbers,
// kept as jobs run (escapes.py): how often a defect gets past every check,
// against a threshold agreed in advance, and what reviews still find that no
// gate does.
import { useState } from 'react';
import { api, type Json } from '../lib/api';
import { useApp, useLoad } from '../lib/app';
import { plural } from '../lib/format';
import { jobHref } from '../lib/router';
import { Time } from '../components/Time';
import { Badge, Card, Empty, External, Field, Fold, PageHeader, StackTable } from '../components/ui';
import { Output } from '../components/Output';
import { OUTCOMES } from './job/Proof';

const percent = (n: number | null | undefined) => (n == null ? '—' : `${Math.round(n * 1000) / 10}%`);

export function Verification() {
  const { data, error } = useLoad(() => api('/wipp/api/verification'), []);
  if (error) return <><PageHeader title="Verification" /><p className="alert">{error}</p></>;
  if (!data) return <PageHeader title="Verification" />;
  const review = data.review || {};
  const categories = Object.entries(review.categories || {}) as [string, Json][];
  const threshold = data.threshold == null ? 'No threshold is set yet (escapes.threshold in factory.yaml): agree one before review is retired.'
    : data.over_threshold ? `Over the threshold of ${percent(data.threshold)}: a repository past it goes back to review.`
    : `Under the threshold of ${percent(data.threshold)}.`;
  return (
    <>
      <PageHeader title="Verification">
        <p className="my-1 text-[22px] font-bold tracking-tight [&_.muted]:text-[15px] [&_.muted]:font-normal">
          {percent(data.rate)} <span className="muted">of {plural(data.shipped, 'shipped job')} in the last {data.window_days} days had an escape.</span></p>
