    let n = |field: &str| stats[field].as_u64().unwrap_or(0);
    Queue {
        name: name.into(),
        depth: n("depth"),
        delivered: n("delivered"),
        failed: n("failed"),
        dead_letters: n("dlq_depth"),
    }
}

