        assert_eq!(calls[1].2["wait_ms"], 5000);
        assert_eq!(calls[1].2["cursors"]["queue"]["offset"], 42);
    }

    #[test]
    fn stop_and_start_name_one_container() {
        let engine = FakeEngine::new(Link::Up)
            .answer("compose::down", Ok(json!({})))
            .answer("compose::up", Ok(json!({})));
