        tauri::async_runtime::block_on(set_running(&engine, "ade", true)).unwrap();
        let calls = engine.calls.lock().unwrap();
        assert_eq!((calls[0].1.as_str(), &calls[0].2), ("compose::down", &json!({ "container": "ade" })));
        assert_eq!(calls[1].1, "compose::up");
    }
}

